import assert from 'node:assert/strict';

export async function checkMicroSyntax(browser, url) {
  const page = await browser.newPage(); page.setDefaultTimeout(10000);
  const stored = () => page.evaluate(() => JSON.parse(localStorage.getItem('bento.prototype.workspace.v4')).workspace);
  const properties = () => page.getByRole('listbox', { name: 'Properties', exact: true });
  const title = () => page.getByRole('textbox', { name: 'Document title', exact: true });
  const errors = []; page.on('pageerror', error => errors.push(error.message));
  try {
    await page.goto(url); await page.getByRole('button', { name: 'Meeting note', exact: true }).click();
    let editor = page.getByRole('textbox', { name: 'Page Markdown', exact: true });
    await editor.press('ControlOrMeta+End'); await editor.press('Enter'); await editor.press('Enter');
    await editor.pressSequentially('[] Micro browser @da ');
    await properties().getByRole('option', { name: /^Due date/ }).waitFor();
    await editor.press('Enter');
    await page.getByRole('dialog', { name: 'Set Due date', exact: true }).getByRole('button', { name: 'Tomorrow', exact: true }).click();
    let workspace = await stored(), task = Object.values(workspace.records).find(record => record.title === 'Micro browser');
    assert.ok(task, JSON.stringify({ titles: Object.values(workspace.records).map(record => record.title), body: workspace.records.coordination.body, errors })); assert.equal(task.properties['field-task-due'], '2026-10-20');
    const inlineTokens = () => page.locator('#b-reading [data-inline-micro]');
    await inlineTokens().filter({ hasText: '@Due date(2026-10-20)' }).waitFor();
    await editor.pressSequentially(' extra');
    assert.equal(await inlineTokens().count(), 1);
    for (let index = 0; index < 6; index++) await editor.press('Backspace');
    await editor.locator(`[data-todo-link="${task.id}"]`).evaluate(paragraph => {
      const range = document.createRange(); range.setStart(paragraph.firstChild, 0); range.collapse(true);
      const selection = getSelection(); selection.removeAllRanges(); selection.addRange(range);
    });
    await editor.pressSequentially('New ');
    await inlineTokens().first().click();
    await page.locator('.b-micro-picker input[type=date]').fill('2026-10-22'); await page.keyboard.press('Enter');
    await inlineTokens().filter({ hasText: '@Due date(2026-10-22)' }).waitFor();
    assert.equal(await inlineTokens().count(), 1);
    await editor.pressSequentially(' extra');
    assert.equal((await stored()).records[task.id].title, 'New Micro browser extra');
    for (let index = 0; index < 6; index++) await editor.press('Backspace');
    await editor.press('Backspace');
    await page.getByRole('dialog', { name: 'Set Due date', exact: true }).waitFor();
    await page.keyboard.press('Escape');
    assert.equal((await stored()).records[task.id].title, 'New Micro browser');
    await inlineTokens().first().click();
    await page.getByRole('dialog', { name: 'Set Due date', exact: true }).getByRole('button', { name: 'Tomorrow', exact: true }).click();
    await editor.pressSequentially(' @pro');
    await properties().getByRole('option', { name: /^Project/ }).click();
    const projectSearch = page.getByRole('searchbox', { name: 'Search Project', exact: true });
    await projectSearch.fill('Elm'); await projectSearch.press('Enter');
    workspace = await stored(); assert.equal(workspace.records[task.id].properties['field-task-project'], 'elm');
    assert.equal(await inlineTokens().count(), 2);
    assert.doesNotMatch(workspace.records.coordination.body, /@da|@pro/);
    await editor.pressSequentially(' @da'); await editor.press('Enter');
    await page.locator('.b-micro-picker input[type=date]').fill('2027-01-05'); await page.keyboard.press('Escape');
    workspace = await stored();
    assert.equal(workspace.records[task.id].properties['field-task-due'], '2026-10-20');
    assert.match(workspace.records.coordination.body, /@da/);
    for (let index = 0; index < 4; index++) await editor.press('Backspace');
    assert.equal((await stored()).records[task.id].title, 'New Micro browser');
    await editor.press('Enter');
    assert.equal(await inlineTokens().count(), 0);
    await editor.press('Enter'); await editor.pressSequentially('@color'); await editor.press('Enter');
    await page.getByRole('listbox', { name: 'Color', exact: true }).selectOption('purple'); await page.keyboard.press('Enter');
    await inlineTokens().waitFor();
    await page.locator('[data-properties-disclosure]>summary').focus();
    await inlineTokens().waitFor({ state: 'detached' });
    assert.equal((await stored()).records.coordination.color, 'purple');
    await page.keyboard.press('ControlOrMeta+Shift+p');
    await page.getByRole('combobox', { name: 'Search pages and commands', exact: true }).fill('>new page in Todos');
    await page.keyboard.press('Enter'); await title().fill('Keyboard entry @da'); await title().press('Enter');
    const dateInput = page.locator('.b-micro-picker input[type=date]');
    await dateInput.fill('2026-10-25'); await dateInput.press('Enter');
    assert.equal(await title().inputValue(), 'Keyboard entry ');
    await page.locator('.b-entry-title [data-edit-entry-field]').filter({ hasText: '@Due date(2026-10-25)' }).waitFor();
    await title().pressSequentially('@pro'); await title().press('Enter');
    await page.getByRole('searchbox', { name: 'Search Project', exact: true }).fill('Elm'); await page.keyboard.press('Enter');
    await title().press('Enter');
    await page.getByRole('textbox', { name: 'Todo Markdown', exact: true }).waitFor();
    workspace = await stored();
    const entry = Object.values(workspace.records).find(record => record.title === 'Keyboard entry');
    assert.equal(entry.properties['field-task-due'], '2026-10-25'); assert.equal(entry.properties['field-task-project'], 'elm');
    await page.getByRole('button', { name: 'Meeting note', exact: true }).click();
    editor = page.getByRole('textbox', { name: 'Page Markdown', exact: true });
    await editor.press('ControlOrMeta+End'); await editor.press('Enter'); await editor.press('Enter');
    await editor.pressSequentially('/Meeting Notes');
    await page.getByRole('listbox', { name: 'Slash commands', exact: true }).getByRole('option', { name: /^New page in Meeting Notes/ }).waitFor();
    await editor.press('Enter'); await title().fill('Slash entry @related'); await title().press('Enter');
    await page.getByRole('searchbox', { name: 'Search Related projects', exact: true }).fill('Elm'); await page.keyboard.press('Enter');
    await title().press('Enter');
    await page.getByRole('textbox', { name: 'Page Markdown', exact: true }).waitFor();
    workspace = await stored();
    const meeting = Object.values(workspace.records).find(record => record.title === 'Slash entry');
    assert.ok(meeting.properties['field-meeting-projects'].includes('elm'));
    assert.doesNotMatch(workspace.records.coordination.body, /\/Meeting Notes/);
    await editor.press('ControlOrMeta+End'); await editor.press('Enter'); await editor.pressSequentially('mail@example.com');
    assert.equal(await page.locator('.b-micro-picker:not([hidden])').count(), 0);
    await editor.press('Enter'); await editor.pressSequentially('``` '); await editor.pressSequentially('@date');
    assert.equal(await page.locator('.b-micro-picker:not([hidden])').count(), 0);
    await page.keyboard.press('ControlOrMeta+Shift+p');
    await page.getByRole('combobox', { name: 'Search pages and commands', exact: true }).fill('>new page in Todos'); await page.keyboard.press('Enter');
    await title().fill('IME title @da'); await properties().waitFor();
    await title().dispatchEvent('compositionstart');
    assert.equal(await page.locator('.b-micro-picker:not([hidden])').count(), 0);
    await title().dispatchEvent('compositionend'); await properties().waitFor();
    await title().press('Escape');
    assert.equal(await title().inputValue(), 'IME title @da');
    await page.getByRole('button', { name: 'Cancel', exact: true }).click();
    assert.deepEqual(errors, []);
    console.log('Passed shared @ properties for checkbox todos, palette entry creation, and slash database creation with keyboard/mouse values and clean metadata.');
  } finally { await page.close(); }
}
